\begin{hebrew}
\beginnumbering
\pstart\relax \OSCondStartInline{}\instructionnote{{{\textdir TRT\foreignlanguage{hebrew}{\OSExpansion{קהל וחזן}}}}} יִמְלֹךְ יְיָ לְעוֹלָם אֱלֹהַיִךְ צִיּוֹן לְדֹר וָדֹר הַלֲלוּיָהּ: \OSCondEndInline{}\pend
\endnumbering
\end{hebrew}
\begin{pairs}
\begin{Leftside}
\setlength{\parskip}{0pt}
\begin{hebrew}
\beginnumbering
\pstart\relax לְדוֹר וָדוֹר נַגִּיד גָּדְלֶךָ וּלְנֵצַח נְצָחִים קְדֻשָּׁתְךָ נַקְדִּישׁ וְשִׁבְחֲךָ אֱלֹהֵינוּ מִפִּינוּ לֹא יָמוּשׁ לְעוֹלָם וָעֶד כִּי אֵל מֶלֶךְ גָּדוֹל וְקָדוֹשׁ אָתָּה. \pend
\pstart\relax וּבְכֵן תֵּן פַּחְדְּךָ יְיָ אֱלֹהֵֽינוּ עַל כָּל־מַעֲשֶׂיךָ וְאֵימָתְךָ עַל כָּל־מַה־שֶּׁבָּרָֽאתָ וְיִירָאוּךָ כָּל־הַמַּעֲשִׂים וְיִשְׁתַּחֲווּ לְפָנֶיךָ כָּל־הַבְּרוּאִים וְיֵעָשׂוּ כֻלָּם אֲגֻדָּה אַחַת לַעֲשׂוֹת רְצוֹנְךָ בְּלֵבָב שָׁלֵם כְּמוֹ שֶׁיָּדַֽעְנוּ יְיָ אֱלֹהֵֽינוּ שֶׁהַשָּׁלְטָן לְפָנֶֽיךָ עֹז בְּיָדַֽךָ וּגְבוּרָה בִּימִינֶךָ וְשִׁמְךָ נוֹרָא עַל כָּל־מַה־שֶּׁבָּרָֽאתָ:\pend
\pstart\relax וּבְכֵן תֵּן כָּבוֹד יְיָ לְעַמֶּךָ תְּהִלָּה לִירֵאֶיךָ וְתִקְוָה לְדוֹרְשֶׁיךָ וּפִתְחוֹן פֶּה לַמְיַחֲלִים לָךְ שִׂמְחָה לְאַרְצֶךָ וְשָׂשׂוֹן לְעִירֶךָ וּצְמִיחַת קֶרֶן לְדָוִד עַבְדֶּךָ וַעֲרִיכַת נֵר לְבֶן־יִשַׁי מְשִׁיחֶךָ בִּמְהֵרָה בְיָמֵינוּ:\pend
\pstart\relax וּבְכֵן צַדִּיקִים יִרְאוּ וְיִשְׂמָחוּ וִישָׁרִים יַעֲלֹזוּ וַחֲסִידִים בְּרִנָּה יָגִילוּ וְעוֹלָתָה תִּקְפָּץ־פִּיהָ. וְכָל־הָרִשְׁעָה כֻּלָּהּ כְּעָשָׁן תִּכְלֶה כִּי תַעֲבִיר מֶמְשֶׁלֶת זָדוֹן מִן־הָאָרֶץ:\pend
